// NOTE on pre-implementation state: lib/admin/catalog.ts still exports the hand-written
// PAGE_CATALOG/PAGE_BY_PATH/ROLE_IDX/seedLevels shape pre-FE-2 — PAGE_GROUPS, ALL_PAGES
// (CatalogPage[]), PAGE_BY_ID, TOTAL_PAGES and the role-code-keyed kFor do not exist yet,
// so every import below fails to resolve until FE-2 lands. That resolution failure is the
// expected pre-implementation signal for this unit.
import { describe, expect, it } from "vitest";

import { PAGES, type PageId, type Role } from "@/lib/pages-config";
import { ALL_PAGES, PAGE_GROUPS, PAGE_BY_ID, TOTAL_PAGES, kFor, ROLE_CODES } from "@/lib/admin/catalog";

describe("FE-2 PAGE_CATALOG derived from PAGES", () => {
  describe("positive — the derived catalog matches PAGES exactly", () => {
    it("ALL_PAGES' page_id set equals PAGES' key set", () => {
      const fromCatalog = ALL_PAGES.map((p) => p.page_id).sort();
      const fromPages = (Object.keys(PAGES) as PageId[]).sort();
      expect(fromCatalog).toEqual(fromPages);
    });

    it("TOTAL_PAGES equals the number of PAGES keys", () => {
      expect(TOTAL_PAGES).toBe(Object.keys(PAGES).length);
    });

    it("group membership follows `subgroup`, with the two hideFromNav pages lacking one landing in a single 'Other' group", () => {
      const otherGroup = PAGE_GROUPS.find(([group]) => group === "Other");
      expect(otherGroup).toBeDefined();
      const otherIds = (otherGroup?.[1] ?? []).map((p) => p.page_id).sort();
      expect(otherIds).toEqual(["compliance.overview", "mobo.recon-overview"].sort());
    });

    it("PAGE_BY_ID resolves every PageId key", () => {
      for (const id of Object.keys(PAGES) as PageId[]) {
        expect(PAGE_BY_ID[id]).toBeDefined();
        expect(PAGE_BY_ID[id].page_id).toBe(id);
      }
    });
  });

  describe("negative — no path literal is reachable from the catalog's own exports", () => {
    it("no CatalogPage carries a path that isn't sourced from PAGES[id].path", () => {
      for (const p of ALL_PAGES) {
        expect(p.path).toBe(PAGES[p.page_id].path);
      }
    });

    it("a lookup by a former path string (e.g. the old '/rm/dashboard') yields nothing", () => {
      const byFormerPath = ALL_PAGES.find((p) => (p as unknown as { path: string }).path === "/rm/dashboard");
      expect(byFormerPath).toBeUndefined();
    });
  });

  describe("invariants", () => {
    it("every page appears in exactly one group", () => {
      const seen = new Map<PageId, number>();
      for (const [, pages] of PAGE_GROUPS) {
        for (const p of pages) seen.set(p.page_id, (seen.get(p.page_id) ?? 0) + 1);
      }
      expect(PAGE_GROUPS.flatMap(([, pages]) => pages).length).toBe(TOTAL_PAGES);
      for (const count of seen.values()) expect(count).toBe(1);
    });

    it("kFor is injective over (PageId, Role) — distinct roles on the same page never collide", () => {
      expect(kFor("pc.allocation-matrix", "PC")).toBe("pc.allocation-matrix|PC");
      expect(kFor("pc.allocation-matrix", "PC")).not.toBe(kFor("pc.allocation-matrix", "PM"));
    });

    it("kFor's output never depends on array position (ROLE_CODES order is not load-bearing)", () => {
      const reordered: Role[] = [...ROLE_CODES].reverse();
      for (const role of reordered) {
        expect(kFor("rm.client-info", role)).toBe(`rm.client-info|${role}`);
      }
    });

  });

  describe("isLocked — module-private to components/admin/config/Matrix.tsx", () => {
    // isLocked has no export in §5.6's public surface, and the contract does not pin
    // Matrix's final row/column data source (PAGE_GROUPS vs. the store's MatrixOut.pages
    // /.roles once FE-9 lands), so a reliable black-box render test would have to guess
    // that integration. Flagged as a §8.3 goal ambiguity in the test-gen report rather
    // than guessed here. The formula itself — `role === "ADMIN" && page_id.startsWith
    // ("admin.")` — is exercised for real by FE-5's guard/nav tests, which do the
    // equivalent ADMIN-only check on a public function (pageIdForPath + groupsFor).
    it("documents the intended formula so a future export makes this file's coverage trivial to extend", () => {
      const isLocked = (pageId: PageId, role: Role) => role === "ADMIN" && pageId.startsWith("admin.");
      expect(isLocked("admin.enroll-user", "ADMIN")).toBe(true);
      expect(isLocked("admin.system-config", "ADMIN")).toBe(true);
      expect(isLocked("admin.enroll-user", "PC")).toBe(false);
      expect(isLocked("rm.client-info", "ADMIN")).toBe(false);
    });
  });
});
